mapper.select:
select c.id , c.nickname , c.comment , c.avatar_no , c.created_at , c.deleted_at , c.post_id , p.title as post_title , p.slug as post_slug , p.post_type as post_type from comments c left join posts p on p.id = c.post_id where c.deleted_at is null
and ( c.nickname ilike '%' || #{search} || '%' or c.comment ilike '%' || #{search} || '%' )
order by c.created_at desc limit #{limit} offset #{offset}
